def print_all_args(*args):
    for arg in args:
        print(arg)

def calculate_product(multiplier, *args):
    result = multiplier
    for num in args:
        result *= num
    return result

def configure_settings(app_name, *options, **config):
    return {
        'app_name': app_name,
        'options': list(options),
        'config': config
    }

def validate_numbers(*args):
    for arg in args:
        if not isinstance(arg, (int, float)):
            return False
    return True

def merge_configs(**configs):
    result = {}
    for config in configs.values():
        result.update(config)
    return result

def create_person(name, age=0, **attrs):
    person = {'name': name, 'age': age}
    person.update(attrs)
    return person

def smart_config(**kwargs):
    allowed = {'host', 'port', 'debug'}
    return {k: v for k, v in kwargs.items() if k in allowed}

def log_arguments(func):
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__} with args: {args}, kwargs: {kwargs}")
        return func(*args, **kwargs)
    return wrapper

@log_arguments
def example_function(a, b, c=0):
    return a + b + c

def build_query(table_name, **conditions):
    where_clause = ''
    if conditions:
        conditions_str = ' AND '.join(f"{k}='{v}'" for k, v in conditions.items())
        where_clause = f' WHERE {conditions_str}'
    return f'SELECT * FROM {table_name}{where_clause}'
